list.items:
@js:(function(){
  function fmt(s){ s=String(s||''); return s.length>=16?s.slice(0,16):s; }
  var raw=typeof result==='string'?JSON.parse(result):result;
  var data=(raw&&raw.data)||{};
  var L=data.comments||[];
  var para=String(data.paragraph||'').replace(/\u3000/g,'').trim();
  var out=[];
  for(var i=0;i<L.length;i++){
    var c=L[i]||{};
    var txt=String(c.content||'').replace(/\[fn=\d+\]/g,'').replace(/\r?\n+/g,' ').trim();
    if(!txt && !c.imageUrl && !c.audioUrl) continue;
    if(!txt) txt='[图片/语音评论]';
    out.push({
      content:txt,
      author:String(c.nickname||'书友'),
      likes:String(c.likeCount||0),
      date:fmt(c.createTime),
      quote:para.slice(0,40),
      reviewId:String(c.reviewId||''),
      isGod:c.isGod?1:0
    });
  }
  return JSON.stringify(out);
})()

