list.items:
@js:(function(){
  function clean(s){return String(s||'').replace(/\u3000/g,'').replace(/<[^>]*>/g,'').replace(/&nbsp;/g,' ').replace(/[\r\n\t]+/g,' ').replace(/\s+/g,' ').trim();}
  var raw=typeof result==='string'?JSON.parse(result):result;
  var body=String((raw&&raw.body)||'');
  var lines=body.split(/\n+/);
  var out=[]; var idx=0;
  for(var i=0;i<lines.length;i++){
    var txt=clean(lines[i]);
    if(!txt) continue;
    idx+=1;
    var quote=txt.slice(0,40); if(quote.length<4) quote=txt;
    var cnt=txt.replace(/\s/g,'').length; if(cnt<=0) continue;
    out.push({count:String(cnt),index:String(idx),id:String(idx),quote:quote});
  }
  return JSON.stringify(out);
})()

counts.paragraphCount:
@js:(function(){
  var raw=typeof result==='string'?JSON.parse(result):result;
  var body=String((raw&&raw.body)||'');
  var lines=body.split(/\n+/); var n=0;
  for(var i=0;i<lines.length;i++){ if(lines[i].replace(/\s/g,'')) n++; }
  return String(n);
})()

